let clicks=0;document.querySelector('#research').addEventListener('click',()=>{document.querySelector('#events').firstChild.textContent='Clicks: '+(++clicks)});document.querySelector('#load').addEventListener('click',()=>{document.querySelector('#lazy').insertAdjacentHTML('beforeend','<article><h2>Newly loaded discussion</h2><p>New content should translate automatically when it enters the reading area.</p></article>')});
